= client_with_catalogs()\\n    assert client.get(PATH + '?orgId=dev-org').status_code == 400\\n    assert not legacy.calls and not reader.calls\\n\\nACTUAL SOURCE services/aos-api/tests/test_ecommerce_workshop_read_http.py\\n\\\"\\\"\\\"HTTP scope fence: only explicitly audited GETs use installed read admission.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom fastapi import FastAPI\\nfrom fastapi.testclient import TestClient\\n\\nfrom aos_api.asset_registry.errors import AssetNotFoundError\\nfrom aos_api.auth import Principal, require_principal\\nfrom aos_api.errors import register_exception_handlers\\nfrom aos_api.routers import ecommerce_workshop as routes\\n\\nROOTS = {\\n    'task-cockpit', 'operations', 'content-campaign', 'creator-growth',\\n    'media-studio', 'analyst', 'price-governance', 'customer',\\n}\\n\\n\\nclass RejectingCatalog:\\n    def __init__(self):\\n        self.calls = []\\n\\n    def get_readiness(self, **scope):\\n        self.calls.append(scope)\\n        raise AssetNotFoundError('not installed in current scoped catalog')\\n\\n\\ndef client_with_catalogs():\\n    app = FastAPI()\\n    register_exception_handlers(app)\\n    app.include_router(routes.router)\\n    legacy, reader = RejectingCatalog(), RejectingCatalog()\\n    app.dependency_overrides[routes.get_ecommerce_workshop_catalog] = lambda: legacy\\n    app.dependency_overrides[routes.get_ecommerce_workshop_read_catalog] = lambda: reader\\n    app.dependency_overrides[require_principal] = lambda: Principal(\\n        subject='scope-test', org_id='org-org', project_id='dev-project',\\n        roles=['admin'], markings=[],\\n    )\\n    return TestClient(app), legacy, reader\\n\\n\\n@pytest.mark.parametrize('module', sorted(ROOTS))\\ndef test_root_get_uses_scoped_read_admission_before_business_reader(module):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get(f'/v1/ecommerce-workshop/views/{module}')\\n    assert response.status_code == 404\\n    assert not legacy.calls\\n    assert len(reader.calls) == 1\\n    assert reader.calls[0] == dict(module_id=f'ecommerce.{module}',\\n        org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])\\n\\n\\n@pytest.mark.parametrize('path', [\\n    '/views/customer/contributions', '/views/creator-growth/contributions',\\n    '/modules/ecommerce.operations/readiness',\\n])\\ndef test_unreviewed_get_still_uses_legacy_admission(path):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get('/v1/ecommerce-workshop' + path)\\n    assert response.status_code == 404\\n    assert legacy.calls\\n    assert not reader.calls\\n\\n\\ndef test_read_dependency_only_reaches_explicit_audited_get_routes():\\n    actual = set()\\n    for route in routes.router.routes:\\n        uses_read = any(d.call is routes.get_ecommerce_workshop_read_catalog\\n                        for d in route.dependant.dependencies)\\n        if uses_read:\\n            assert route.methods == {'GET'}\\n            actual.add(route.path)\\n    assert actual == {f'/v1/ecommerce-workshop/views/{m}' for m in ROOTS} | {\\n        '/v1/ecommerce-workshop/views/operations/cases',\\n        '/v1/ecommerce-workshop/commands/operations/readiness',\\n        '/v1/ecommerce-workshop/views/task-cockpit/feedback',\\n        '/v1/ecommerce-workshop/views/task-cockpit/dispatch-scenario',\\n        '/v1/ecommerce-workshop/views/task-cockpit/batch-scenario',\\n        '/v1/ecommerce-workshop/views/media-studio/full-production-scenario',\\n        '/v1/ecommerce-workshop/views/media-studio/workflow/drafts',\\n        '/v1/ecommerce-workshop/views/analyst/learning-scenario',\\n    }\\n\\n\\ndef test_unknown_query_rejected_before_catalog_call():\\n    client, legacy, reader = client_with_catalogs()\\n    assert client.get('/v1/ecommerce-workshop/views/operations?orgId=dev-org').status_code == 400\\n    assert not legacy.calls and not reader.calls\\n\\n\\nclass ReadReached(RuntimeError):\\n    pass\\n\\n\\n@pytest.mark.parametrize('module', sorted(ROOTS))\\ndef test_admitted_root_reaches_reader_with_authenticated_tenant(module):\\n    client, legacy, reader = client_with_catalogs()\\n    def admit(**scope):\\n        reader.calls.append(scope)\\n    reader.get_readiness = admit\\n    factory = getattr(routes, 'get_ecommerce_workshop_' + module.replace('-', '_'))\\n    class ProbeReader:\\n        def read(self, **scope):\\n            assert scope['org_id'] == 'org-org'\\n            assert scope['project_id'] == 'dev-project'\\n            raise ReadReached(module)\\n        read_core = read\\n    client.app.dependency_overrides[factory] = lambda: ProbeReader()\\n    with pytest.raises(ReadReached, match=module):\\n        client.get('/v1/ecommerce-workshop/views/' + module)\\n    assert not legacy.calls\\n    assert len(reader.calls) == 1\\n\\n\\ndef test_legacy_success_does_not_build_installed_configuration(monkeypatch):\\n    from aos_api import ecommerce_installed_readonly_catalog as installed\\n    sentinel = object()\\n    class Legacy:\\n        def get_readiness(self, **scope):\\n            return sentinel\\n    def forbidden():\\n        pytest.fail('successful legacy must not inspect selected configuration')\\n    monkeypatch.setattr(installed, 'build_installed_readonly_catalog', forbidden)\\n    catalog = routes.get_ecommerce_workshop_read_catalog(Legacy())\\n    assert catalog.get_readiness(module_id='ecommerce.operations') is sentinel\\n\\n\\ndef test_installed_factory_is_deferred_until_legacy_not_found(monkeypatch):\\n    from aos_api import ecommerce_installed_readonly_catalog as installed\\n    calls = []\\n    def selected():\\n        calls.append('selected')\\n        raise ValueError('configuration sentinel')\\n    monkeypatch.setattr(installed, 'build_installed_readonly_catalog', selected)\\n    catalog = routes.get_ecommerce_workshop_read_catalog(RejectingCatalog())\\n    assert not calls\\n    with pytest.raises(ValueError, match='configuration sentinel'):\\n        catalog.get_readiness(module_id='ecommerce.operations')\\n    assert calls == ['selected']\\n\\nCANDIDATE DIFF\\ndiff --git a/services/aos-api/aos_api/routers/ecommerce_workshop.py b/services/aos-api/aos_api/routers/ecommerce_workshop.py\\nindex ac0e8ad0f..166999dc6 100644\\n--- a/services/aos-api/aos_api/routers/ecommerce_workshop.py\\n+++ b/services/aos-api/aos_api/routers/ecommerce_workshop.py\\n@@ -1981,7 +1981,7 @@ def get_ecommerce_workshop_analyst_view(\\n def get_ecommerce_workshop_analyst_learning_scenario(\\n     request: Request,\\n     principal: PrincipalDependency,\\n-    catalog: CatalogDependency,\\n+    catalog: ReadCatalogDependency,\\n     scenario: LearningScenarioDependency,\\n ) -> LearningScenarioContribution:\\n     _reject_unknown_query_parameters(request, allowed=frozenset())\\n\\nACTUAL ROUTER SOURCE get_ecommerce_workshop_learning_scenario LINE 580\\ndef get_ecommerce_workshop_learning_scenario() -> EcommerceWorkshopLearningScenario:\\n    return EcommerceWorkshopLearningScenario()\\n\\nACTUAL ROUTER SOURCE get_ecommerce_workshop_analyst_learning_scenario LINE 1981\\ndef get_ecommerce_workshop_analyst_learning_scenario(\\n    request: Request,\\n    principal: PrincipalDependency,\\n    catalog: ReadCatalogDependency,\\n    scenario: LearningScenarioDependency,\\n) -> LearningScenarioContribution:\\n    _reject_unknown_query_parameters(request, allowed=frozenset())\\n    _require_analyst_installation(principal=principal, catalog=catalog)\\n    return scenario.read(\\n        scope=TenantScope(principal.org_id, principal.project_id),\\n        cutoff=datetime.now(UTC),\\n    )\\n\\nACTUAL ROUTER SOURCE _require_analyst_installation LINE 1034\\ndef _require_analyst_installation(\\n    *, principal: Principal, catalog: EcommerceWorkshopCatalog\\n) -> None:\\n    _invoke(\\n        lambda: catalog.get_readiness(\\n            module_id=\\\"ecommerce.analyst\\\",\\n            org_id=principal.org_id,\\n            project_id=principal.project_id,\\n            roles=principal.roles,\\n            markings=principal.markings,\\n        )\\n    )\\n\\nORIGINAL LEARNING ADJACENT SOURCE\\n\\\"\\\"\\\"W8-04 EffectReview-rooted governed learning scenario tests.\\\"\\\"\\\"\\n\\nfrom datetime import UTC, datetime\\n\\nimport pytest\\nfrom pydantic import ValidationError\\n\\nfrom aos_api.ecommerce_workshop_learning_scenario import (\\n    EcommerceWorkshopLearningScenario,\\n    LearningScenarioObservation,\\n    learning_binding_hash,\\n)\\nfrom aos_api.ecommerce_workshop_learning_scenario_contracts import (\\n    LearningScenarioBlocker,\\n    LearningScenarioComposition,\\n    LearningScenarioContribution,\\n    LearningScenarioExactRef,\\n    LearningScenarioLedger,\\n    LearningScenarioOutcomeAxis,\\n    LearningScenarioOutcomeAxisId,\\n    LearningScenarioRoleBinding,\\n    LearningScenarioStage,\\n    LearningScenarioStageId,\\n)\\nfrom aos_api.tenant_scope import TenantScope\\n\\n\\nCUTOFF = datetime(2026, 8, 26, 5, tzinfo=UTC)\\nSCOPE = TenantScope(org_id=\\\"org-org\\\", project_id=\\\"dev-project\\\")\\nHASH = \\\"sha256:\\\" + \\\"a\\\" * 64\\n\\n\\ndef ref(resource_type: str, resource_id: str) -> LearningScenarioExactRef:\\n    return LearningScenarioExactRef(resourceType=resource_type, resourceId=resource_id, revision=1, contentHash=HASH)\\n\\n\\ndef blocker(code: str) -> LearningScenarioBlocker:\\n    return LearningScenarioBlocker(code=code, dependency=\\\"workshop.learning-scenario\\\", requiredAction=\\\"provide exact current evidence\\\")\\n\\n\\ndef composition() -> LearningScenarioComposition:\\n    return LearningScenarioComposition(\\n        atomicSkillRefs=[ref(\\\"SkillRevision\\\", \\\"review-outcomes\\\"), ref(\\\"SkillRevision\\\", \\\"govern-knowledge\\\")],\\n        logicRevisionRef=ref(\\\"LogicRevision\\\", \\\"effect-to-governed-knowledge\\\"),\\n        roleBindings=[\\n            LearningScenarioRoleBinding(\\n                roleRef=ref(\\\"AgentTemplate\\\", \\\"analyst\\\"),\\n                assigneeRef=ref(\\\"AgentInstance\\\", \\\"analyst-1\\\"),\\n                skillBindingRef=ref(\\\"SkillBinding\\\", \\\"learning-binding-1\\\"),\\n            )\\n        ],\\n    )\\n\\n\\ndef stages(\\n    review: LearningScenarioExactRef | None = None,\\n    maturity: LearningScenarioExactRef | None = None,\\n) -> tuple[LearningScenarioStage, ...]:\\n    review = review or ref(\\\"EffectReviewRevision\\\", \\\"review-1\\\")\\n    maturity = maturity or ref(\\\"EffectMaturityPolicyRevision\\\", \\\"maturity-1\\\")\\n    refs = [\\n        [review],\\n        [maturity, ref(\\\"EffectMaturityDecision\\\", \\\"maturity-decision-1\\\")],\\n        [ref(\\\"MemoryCandidateRevision\\\", \\\"candidate-1\\\")],\\n        [ref(\\\"GovernanceApprovalRevision\\\", \\\"approval-1\\\")],\\n        [ref(\\\"PromotionReceiptRevision\\\", \\\"promotion-1\\\"), ref(\\\"WikiRevision\\\", \\\"wiki-1\\\")],\\n        [ref(\\\"KnowledgeCitationRevision\\\", \\\"citation-1\\\")],\\n        [],\\n    ]\\n    values: list[LearningScenarioStage] = []\\n    for index, stage in enumerate(LearningScenarioStageId):\\n        if stage is LearningScenarioStageId.REVOCATION_IMPACT:\\n            values.append(LearningScenarioStage(stageId=stage, status=\\\"unknown\\\", contribution=\\\"等待撤销影响确认\\\", blockers=[blocker(\\\"REVOCATION_IMPACT_REVIEW_REQUIRED\\\")]))\\n        else:\\n            values.append(LearningScenarioStage(stageId=stage, status=\\\"ready\\\", exactRefs=refs[index], contribution=f\\\"stage {stage.value}\\\"))\\n    return tuple(values)\\n\\n\\ndef axes(*, all_ready: bool = False) -> tuple[LearningScenarioOutcomeAxis, ...]:\\n    result = [\\n        LearningScenarioOutcomeAxis(axisId=axis, status=\\\"ready\\\", exactRef=ref(\\\"LearningOutcomeRevision\\\", axis.value))\\n        for axis in LearningScenarioOutcomeAxisId\\n    ]\\n    if not all_ready:\\n        result[-1] = LearningScenarioOutcomeAxis(\\n            axisId=LearningScenarioOutcomeAxisId.REVOCATION_IMPACT_RECORDED,\\n            status=\\\"unknown\\\",\\n            blocker=blocker(\\\"REVOCATION_IMPACT_REVIEW_REQUIRED\\\"),\\n        )\\n    return tuple(result)\\n\\n\\ndef ledger() -> LearningScenarioLedger:\\n    return LearningScenarioLedger(\\n        reviewsExpected=1,\\n        reviewsObserved=1,\\n        candidatesExpected=1,\\n        candidatesObserved=1,\\n        promotionsExpected=1,\\n        promotionsObserved=1,\\n        citationsExpected=1,\\n        citationsObserved=1,\\n        historicalExposures=2,\\n        retainedExposures=2,\\n        impactRefsExpected=1,\\n        impactRefsObserved=0,\\n    )\\n\\n\\nclass Reader:\\n    def __init__(self, *, scope: TenantScope = SCOPE, binding: str | None = None, root_drift: bool = False, all_ready: bool = False) -> None:\\n        self.scope = scope\\n        self.binding = binding\\n        self.root_drift = root_drift\\n        self.all_ready = all_ready\\n\\n    def read_scenario(self, scope: TenantScope, *, cutoff: datetime) -> LearningScenarioObservation:\\n        review = ref(\\\"EffectReviewRevision\\\", \\\"review-1\\\")\\n        maturity = ref(\\\"EffectMaturityPolicyRevision\\\", \\\"maturity-1\\\")\\n        layers = composition()\\n        stage_items = stages(ref(\\\"EffectReviewRevision\\\", \\\"review-drift\\\") if self.root_drift else review, maturity)\\n        if self.all_ready:\\n            stage_items = stage_items[:-1] + (\\n                LearningScenarioStage(stageId=LearningScenarioStageId.REVOCATION_IMPACT, status=\\\"ready\\\", exactRefs=[ref(\\\"RevocationImpactRevision\\\", \\\"impact-1\\\")], contribution=\\\"impact ready\\\"),\\n            )\\n        return LearningScenarioObservation(\\n            scope=self.scope,\\n            cutoff=cutoff,\\n            root_effect_review_ref=review,\\n            maturity_policy_ref=maturity,\\n            learning_binding_hash=self.binding or learning_binding_hash(review, maturity, layers, stage_items),\\n            composition=layers,\\n            stages=stage_items,\\n            ledger=ledger(),\\n            outcome_axes=axes(all_ready=self.all_ready),\\n        )\\n\\n\\ndef test_missing_root_returns_structured_blocked_contribution() -> None:\\n    result = EcommerceWorkshopLearningScenario().read(scope=SCOPE, cutoff=CUTOFF)\\n    assert result.root_effect_review_ref is None\\n    assert [item.stage_id for item in result.stages] == list(LearningScenarioStageId)\\n    assert [item.axis_id for item in result.outcome_axes] == list(LearningScenarioOutcomeAxisId)\\n    assert result.commands.model_dump() == {\\n        \\\"submit_candidate\\\": False,\\n        \\\"approve_candidate\\\": False,\\n        \\\"promote_candidate\\\": False,\\n        \\\"publish_wiki\\\": False,\\n        \\\"revoke_knowledge\\\": False,\\n    }\\n    assert result.external_effects_allowed is False\\n\\n\\ndef test_exact_binding_keeps_skill_logic_role_and_governance_axes_separate() -> None:\\n    result = EcommerceWorkshopLearningScenario(reader=Reader()).read(scope=SCOPE, cutoff=CUTOFF)\\n    assert result.root_effect_review_ref and result.root_effect_review_ref.resource_type == \\\"EffectReviewRevision\\\"\\n    assert result.composition and len(result.composition.atomic_skill_refs) == 2\\n    assert result.composition.logic_revision_ref.resource_type == \\\"LogicRevision\\\"\\n    assert result.composition.role_bindings[0].skill_binding_ref.resource_type == \\\"SkillBinding\\\"\\n    assert [item.status for item in result.outcome_axes] == [\\\"ready\\\", \\\"ready\\\", \\\"ready\\\", \\\"ready\\\", \\\"unknown\\\"]\\n    assert result.ledger.historical_exposures == result.ledger.retained_exposures == 2\\n    assert result.status == \\\"blocked\\\"\\n\\n\\ndef test_cross_tenant_binding_and_root_drift_fail_closed_without_refs() -> None:\\n    other = TenantScope(org_id=\\\"dev-org\\\", project_id=\\\"dev-project\\\")\\n